const C = 1e-9; // 1 nanofaradio: capacitancia efectiva inventada para practicar
const puntos = [[1.2, 0.7], [2.4, 0.8], [3.0, 1.0], [3.6, 1.2]]; // [GHz, voltios]
const base = C * 1.0 * 1.0 * 3.0e9;
for (const [fGHz, V] of puntos) {
  const P = C * V * V * fGHz * 1e9;          // watts
  const porCiclo = C * V * V * 1e9;          // nanojoules por ciclo (no depende de f)
  console.log(`${fGHz} GHz y ${V} V: ${P.toFixed(2)} W (${(P / base * 100).toFixed(0)} % de la de 3 GHz), ${porCiclo.toFixed(2)} nJ por ciclo`);
}
